import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a dummy contract that reverts on transferFrom
        DummyToken dummy = new DummyToken();
        address dummyAddr = address(dummy);
        address from = address(0x123);
        address[] memory tos = new address[](1);
        tos[0] = address(0x456);
        uint v = 100;

        // Call transfer: the external call to dummy.transferFrom will revert
        bool ok;
        try c.transfer(from, dummyAddr, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference version should revert, so ok is false; the buggy version returns true, so ok is true.
