pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a mock token that will revert on the second transferFrom
        MockToken token = new MockToken();
        address tokenAddr = address(token);
        address from = address(0x123);
        address[] memory tos = new address[](2);
        tos[0] = address(0x1);
        tos[1] = address(0x2);
        uint v = 100;
        // Set the mock to revert on the second call (index 1)
        token.setRevertOnSecond(true);
        // Call transfer – this will revert in the reference version because the second call reverts
        // In the second version it won't revert because _s is not checked
        bool ok;
        try c.transfer(from, tokenAddr, tos, v) {
            ok = true;
        } catch {
            ok = false;
        }
        // The reference version will revert (ok == false), the buggy version will succeed (ok == true)
        // We assert that the reference version reverts, meaning ok is false
        // But for the test to FAIL on the buggy version, we assert that ok is true (which only the buggy version does)
        // Wait — the instruction: test PASSES on reference, FAILS on second.
        // So we need the assertion to be true on reference and false on buggy.
        // Reference: revert -> ok = false -> assertTrue(ok) would fail (bad).
        // Instead, assert that ok is false: assertTrue(!ok). Reference passes (ok false), buggy fails (ok true).
        assertTrue(!ok);
    }
}

contract MockToken {
    bool public revertOnSecond;
    uint public callCount;
    function setRevertOnSecond(bool val) public { revertOnSecond = val; }
    function transferFrom(address, address, uint256) public returns (bool) {
        callCount++;
        if (revertOnSecond && callCount == 2) {
            revert("second call revert");
        }
        return true;
    }
}

