import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testRegression_property() public {
        // Deploy a minimal ERC20-like token that tracks balances and has a transferFrom function
        Token t = new Token();
        // Set up addresses
        address from = address(0x123);
        address to = address(0x456);
        // Give from initial tokens (mint 100)
        t.mint(from, 100);
        address[] memory tos = new address[](1);
        tos[0] = to;
        // Have from approve the contract C to transfer 50
        vm.prank(from);
        t.approve(address(c), 50);
        // Call transfer with caddress = token, v = 50
        vm.prank(from);
        c.transfer(from, address(t), tos, 50);
        // Assert that to's balance is 50 (reference: transferFrom succeeds correctly)
        // In the buggy version (delegatecall), the token's storage is not updated, so balance remains 0
        assertEq(t.balanceOf(to), 50);
    }
}

// Minimal token contract with needed functions
contract Token {
    mapping(address => uint256) public balanceOf;
    mapping(address => mapping(address => uint256)) public allowance;

    function mint(address to, uint256 amount) external {
        balanceOf[to] += amount;
    }

    function approve(address spender, uint256 amount) external returns (bool) {
        allowance[msg.sender][spender] = amount;
        return true;
    }

    function transferFrom(address from, address to, uint256 amount) external returns (bool) {
        require(allowance[from][msg.sender] >= amount, "allowance too low");
        require(balanceOf[from] >= amount, "balance too low");
        allowance[from][msg.sender] -= amount;
        balanceOf[from] -= amount;
        balanceOf[to] += amount;
        return true;
    }
}

